//! T24: Feishu sign-in refusals and conversation discovery against a mock
//! server (scenario feishu_discovery_mock). Discovery responses come from the
//! committed fixture generated by the real service (T03p).
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use vox_agent_desktop_tauri_lib::context_account::{
    decode_conversations, discover, logout, AccountError, ConversationKind, DiscoveryError,
};
use vox_agent_desktop_tauri_lib::context_login::{sign_in, LoginError};
use vox_agent_desktop_tauri_lib::context_wire::ContextEndpoint;

const REQUEST: &str = "req_0123456789abcdefghijklmnopqrstuvwxyzABCDEF";
const COMPLETION: &str = "cmp_0123456789abcdefghijklmnopqrstuvwxyzABCDEF";
const POLL: &str = "poll_0123456789abcdefghijklmnopqrstuvwxyzABCDEF";
const TOKEN: &str = "vox_sso_0123456789abcdefghijklmnopqrstuvwxyzAB";
const ACTOR: &str = "feishu-0123456789abcdef0123456789abcdef";
const DM: &str = "fc_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
const GROUP: &str = "fc_BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB";

#[derive(Clone)]
struct Route {
    line: &'static str,
    status: String,
    body: String,
}

fn route(line: &'static str, status: &str, body: &str) -> Route {
    Route {
        line,
        status: status.to_string(),
        body: body.to_string(),
    }
}

#[derive(Default)]
struct Seen {
    lines: Vec<String>,
    heads: Vec<String>,
    begin_body: String,
}

fn read_request(stream: &mut TcpStream) -> (String, String, String) {
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .unwrap();
    let mut data = Vec::new();
    let mut buffer = [0u8; 4096];
    loop {
        let n = stream.read(&mut buffer).unwrap_or(0);
        if n == 0 {
            break;
        }
        data.extend_from_slice(&buffer[..n]);
        let text = String::from_utf8_lossy(&data).to_string();
        if let Some(end) = text.find("\r\n\r\n") {
            let length = text[..end]
                .lines()
                .find_map(|l| {
                    l.to_ascii_lowercase()
                        .strip_prefix("content-length:")
                        .map(|v| v.trim().parse::<usize>().unwrap())
                })
                .unwrap_or(0);
            if data.len() >= end + 4 + length {
                return (
                    text.lines().next().unwrap().to_string(),
                    text[..end].to_string(),
                    text[end + 4..].to_string(),
                );
            }
        }
    }
    (String::new(), String::new(), String::new())
}

/// Answers each request with the first route whose request line starts with
/// `route.line`; `{base}` in a body becomes the server origin.
fn server(routes: Vec<Route>) -> (String, Arc<Mutex<Seen>>) {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let origin = format!("http://{}", listener.local_addr().unwrap());
    let seen = Arc::new(Mutex::new(Seen::default()));
    let record = seen.clone();
    let base = origin.clone();
    thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { return };
            let (line, head, body) = read_request(&mut stream);
            {
                let mut seen = record.lock().unwrap();
                seen.lines.push(line.clone());
                seen.heads.push(head);
                if line.starts_with("POST /v1/auth/feishu/begin ") {
                    seen.begin_body = body;
                }
            }
            let found = routes.iter().find(|r| line.starts_with(r.line)).cloned();
            let (status, body) = match found {
                Some(r) => (r.status, r.body.replace("{base}", &base)),
                None => ("404 Not Found".into(), r#"{"detail":"NOT_FOUND"}"#.into()),
            };
            let _ = write!(
                stream,
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
        }
    });
    (origin, seen)
}

fn begun() -> Route {
    route(
        "POST /v1/auth/feishu/begin ",
        "200 OK",
        &format!(
            r#"{{"requestId":"{REQUEST}","pollSecret":"{POLL}","expiresIn":300,"browserURL":"{{base}}/v1/auth/feishu/browser?state={REQUEST}"}}"#
        ),
    )
}

/// Completes the browser step by calling the loopback port the client sent.
fn browser(seen: Arc<Mutex<Seen>>) -> impl FnOnce(&reqwest::Url) -> Result<(), ()> {
    move |_url| {
        let body = seen.lock().unwrap().begin_body.clone();
        let port = serde_json::from_str::<serde_json::Value>(&body).unwrap()["loopbackPort"]
            .as_u64()
            .unwrap() as u16;
        thread::spawn(move || {
            let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
            write!(
                stream,
                "GET /vox-agent/login-complete?requestId={REQUEST}&completion={COMPLETION} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n\r\n"
            )
            .unwrap();
            let mut sink = String::new();
            let _ = stream.read_to_string(&mut sink);
        });
        Ok(())
    }
}

async fn sign_in_with(routes: Vec<Route>) -> Result<(), LoginError> {
    let (origin, seen) = server(routes);
    let endpoint = ContextEndpoint::parse(&origin).unwrap();
    sign_in(&endpoint, browser(seen), Duration::from_secs(10))
        .await
        .map(|_| ())
}

#[tokio::test(flavor = "multi_thread")]
async fn sign_in_refusals_are_reported_as_what_they_are() {
    let redeem = |status: &str, body: &str| {
        vec![begun(), route("POST /v1/auth/feishu/redeem ", status, body)]
    };
    assert_eq!(
        sign_in_with(redeem("403 Forbidden", r#"{"detail":"ACCOUNT_DISABLED"}"#)).await,
        Err(LoginError::AccountDisabled)
    );
    assert_eq!(
        sign_in_with(redeem(
            "403 Forbidden",
            r#"{"detail":"ORGANIZATION_NOT_CONFIGURED"}"#
        ))
        .await,
        Err(LoginError::OrganizationNotConfigured)
    );
    assert_eq!(
        sign_in_with(redeem("410 Gone", r#"{"detail":"LOGIN_EXPIRED"}"#)).await,
        Err(LoginError::Expired)
    );
    assert_eq!(
        sign_in_with(vec![route(
            "POST /v1/auth/feishu/begin ",
            "429 Too Many Requests",
            r#"{"detail":"LOGIN_RATE_LIMIT"}"#
        )])
        .await,
        Err(LoginError::RateLimited)
    );
    assert_eq!(
        sign_in_with(vec![route(
            "POST /v1/auth/feishu/begin ",
            "503 Service Unavailable",
            r#"{"detail":"FEISHU_LOGIN_NOT_CONFIGURED"}"#
        )])
        .await,
        Err(LoginError::NotConfigured)
    );
    // Unknown refusals keep their status; the body is never surfaced.
    assert_eq!(
        sign_in_with(redeem("403 Forbidden", r#"{"detail":"SOMETHING_NEW"}"#)).await,
        Err(LoginError::Refused(403))
    );
    assert_eq!(
        sign_in_with(redeem("500 Internal Server Error", &"x".repeat(100_000))).await,
        Err(LoginError::Refused(500))
    );
}

#[test]
fn every_login_and_discovery_error_has_a_user_facing_code() {
    for error in [
        LoginError::Listener,
        LoginError::Network,
        LoginError::Refused(418),
        LoginError::Denied,
        LoginError::Timeout,
        LoginError::TooManyAttempts,
        LoginError::InvalidResponse,
        LoginError::UnexpectedBrowserUrl,
        LoginError::BrowserUnavailable,
        LoginError::AccountDisabled,
        LoginError::OrganizationNotConfigured,
        LoginError::RateLimited,
        LoginError::NotConfigured,
        LoginError::Expired,
    ] {
        let code = serde_json::to_value(AccountError::from(error)).unwrap();
        assert!(code.as_str().is_some_and(|c| !c.is_empty()), "{error:?}");
    }
    assert_eq!(
        AccountError::from(LoginError::AccountDisabled),
        AccountError::AccountDisabled
    );
    assert_eq!(
        AccountError::from(DiscoveryError::IdentityChanged),
        AccountError::IdentityChanged
    );
}

// ---------- discovery ----------

fn fixture_case(name: &str) -> (u16, String) {
    let text = include_str!("../../test/fixtures/context-extended-wire-v1.json");
    let fixture: serde_json::Value = serde_json::from_str(text).unwrap();
    let case = fixture["conversations"]["http_cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["name"] == name)
        .unwrap()
        .clone();
    let status = case["response"]["status"].as_u64().unwrap() as u16;
    let body = case["response"]["body"]
        .to_string()
        .replace("<id-2>", ACTOR)
        .replace("<id-3>", DM)
        .replace("<id-4>", GROUP);
    (status, body)
}

fn status_line(status: u16) -> String {
    format!("{status} Status")
}

async fn discover_with(status: &str, body: &str, actor: &str) -> Result<usize, DiscoveryError> {
    let (origin, seen) = server(vec![route("GET /v1/conversations ", status, body)]);
    let endpoint = ContextEndpoint::parse(&origin).unwrap();
    let result = discover(&endpoint, TOKEN, actor).await;
    let seen = seen.lock().unwrap();
    assert_eq!(seen.lines.len(), 1);
    assert!(seen.heads[0].to_ascii_lowercase().contains(&format!(
        "authorization: bearer {}",
        TOKEN.to_ascii_lowercase()
    )));
    result.map(|d| d.conversations.len())
}

#[tokio::test(flavor = "multi_thread")]
async fn discovery_lists_the_fixture_conversations_for_the_signed_in_identity() {
    let (status, body) = fixture_case("list");
    assert_eq!(status, 200);
    let (origin, _) = server(vec![route("GET /v1/conversations ", "200 OK", &body)]);
    let endpoint = ContextEndpoint::parse(&origin).unwrap();
    let found = discover(&endpoint, TOKEN, ACTOR).await.unwrap();
    assert_eq!(found.omitted, 0);
    let summary: Vec<_> = found
        .conversations
        .iter()
        .map(|c| (c.id.as_str(), c.kind, c.name.as_str(), c.can_send))
        .collect();
    assert_eq!(
        summary,
        vec![
            (DM, ConversationKind::Personal, "Feishu CLI", true),
            (GROUP, ConversationKind::Group, "oc_one", true),
        ]
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn a_listing_for_another_identity_is_refused() {
    let (_, body) = fixture_case("list");
    assert_eq!(
        discover_with("200 OK", &body, "feishu-someone-else").await,
        Err(DiscoveryError::IdentityChanged)
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn discovery_refusals_are_reported_as_what_they_are() {
    let (status, body) = fixture_case("list_no_auth");
    assert_eq!(
        discover_with(&status_line(status), &body, ACTOR).await,
        Err(DiscoveryError::SignInRequired)
    );
    for (status, body, expected) in [
        (
            "401 Unauthorized",
            r#"{"detail":"SESSION_EXPIRED"}"#,
            DiscoveryError::SignInRequired,
        ),
        (
            "403 Forbidden",
            r#"{"detail":"FEISHU_PRINCIPAL_REQUIRED"}"#,
            DiscoveryError::NotPermitted,
        ),
        (
            "403 Forbidden",
            r#"{"detail":"PERMISSION_DENIED"}"#,
            DiscoveryError::NotPermitted,
        ),
        (
            "403 Forbidden",
            r#"{"detail":"ACCOUNT_DISABLED"}"#,
            DiscoveryError::AccountDisabled,
        ),
        (
            "429 Too Many Requests",
            r#"{"detail":"RATE_LIMITED"}"#,
            DiscoveryError::RateLimited,
        ),
        (
            "503 Service Unavailable",
            r#"{"detail":"CONVERSATIONS_UNAVAILABLE"}"#,
            DiscoveryError::Unavailable,
        ),
        (
            "503 Service Unavailable",
            r#"{"detail":"IDENTITY_MISMATCH"}"#,
            DiscoveryError::Unavailable,
        ),
        (
            "500 Internal Server Error",
            "boom",
            DiscoveryError::Unavailable,
        ),
        ("302 Found", "{}", DiscoveryError::Unavailable),
    ] {
        assert_eq!(
            discover_with(status, body, ACTOR).await,
            Err(expected),
            "{status} {body}"
        );
    }
}

#[test]
fn malformed_entries_are_left_out_and_malformed_listings_refused() {
    let listing = |items: &str| {
        format!(
            r#"{{"identity":{{"appId":"cli_test","tenantKey":"team","userId":"{ACTOR}"}},"conversations":[{items}]}}"#
        )
    };
    let good = format!(
        r#"{{"id":"{DM}","kind":"personal","name":"Feishu CLI","capability":"discovery_only"}}"#
    );
    let items = [
        good.clone(),
        r#"{"id":"oc_raw_chat_id","kind":"group","name":"x","capability":"text_send"}"#.into(),
        format!(r#"{{"id":"{GROUP}","kind":"channel","name":"x","capability":"text_send"}}"#),
        format!(r#"{{"id":"{GROUP}","kind":"group","name":"bad\nname","capability":"text_send"}}"#),
        format!(r#"{{"id":"{GROUP}","kind":"group","name":"   ","capability":"text_send"}}"#),
        format!(r#"{{"id":"{GROUP}","kind":"group","name":"x","capability":"admin"}}"#),
    ]
    .join(",");
    let found = decode_conversations(listing(&items).as_bytes(), ACTOR).unwrap();
    assert_eq!(found.conversations.len(), 1);
    assert!(
        !found.conversations[0].can_send,
        "discovery_only cannot send"
    );
    assert_eq!(found.omitted, 5);

    // Duplicate ids keep only the first entry.
    let twice = decode_conversations(listing(&format!("{good},{good}")).as_bytes(), ACTOR).unwrap();
    assert_eq!((twice.conversations.len(), twice.omitted), (1, 1));

    for bad in [
        "not json".to_string(),
        r#"{"conversations":[]}"#.to_string(),
        format!(r#"{{"identity":{{"userId":"{ACTOR}"}}}}"#),
        listing(&vec![good.clone(); 501].join(",")),
    ] {
        assert!(
            decode_conversations(bad.as_bytes(), ACTOR).is_err(),
            "{bad:.60}"
        );
    }
    assert_eq!(
        decode_conversations(&vec![b' '; 300_000], ACTOR).err(),
        Some(DiscoveryError::InvalidResponse)
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn logout_reports_whether_the_server_ended_the_session() {
    let (origin, seen) = server(vec![route(
        "POST /v1/auth/feishu/logout ",
        "200 OK",
        r#"{"status":"signed_out"}"#,
    )]);
    let endpoint = ContextEndpoint::parse(&origin).unwrap();
    assert!(logout(&endpoint, TOKEN).await);
    assert!(seen.lock().unwrap().heads[0]
        .to_ascii_lowercase()
        .contains(&format!(
            "authorization: bearer {}",
            TOKEN.to_ascii_lowercase()
        )));

    let (origin, _) = server(vec![route(
        "POST /v1/auth/feishu/logout ",
        "401 Unauthorized",
        r#"{"detail":"AUTH_REQUIRED"}"#,
    )]);
    assert!(!logout(&ContextEndpoint::parse(&origin).unwrap(), TOKEN).await);
    let closed = TcpListener::bind("127.0.0.1:0").unwrap();
    let port = closed.local_addr().unwrap().port();
    drop(closed);
    let gone = ContextEndpoint::parse(&format!("http://127.0.0.1:{port}")).unwrap();
    assert!(!logout(&gone, TOKEN).await);
}

// ---------- account transaction (sign-in, sign-out, shared credential store) ----------

use std::collections::HashMap;
use vox_agent_desktop_tauri_lib::context_account::AccountSlot;
use vox_agent_desktop_tauri_lib::context_login::SignedIn;
use vox_agent_desktop_tauri_lib::context_session::{DestinationKey, PrincipalKey, TokenStore};
use vox_agent_desktop_tauri_lib::secrets::SecretError;

/// One shared in-memory credential store, like the OS store all sessions use.
#[derive(Clone, Default)]
struct MemoryStore {
    values: Arc<Mutex<HashMap<String, String>>>,
    broken: Arc<Mutex<bool>>,
}

impl TokenStore for MemoryStore {
    fn read(&self, account: &str) -> Result<Option<String>, SecretError> {
        Ok(self.values.lock().unwrap().get(account).cloned())
    }
    fn write(&self, account: &str, value: &str) -> Result<(), SecretError> {
        if *self.broken.lock().unwrap() {
            return Err(SecretError::Backend);
        }
        self.values
            .lock()
            .unwrap()
            .insert(account.into(), value.into());
        Ok(())
    }
    fn delete(&self, account: &str) -> Result<(), SecretError> {
        if *self.broken.lock().unwrap() {
            return Err(SecretError::Backend);
        }
        self.values.lock().unwrap().remove(account);
        Ok(())
    }
}

impl MemoryStore {
    fn token(&self) -> Option<String> {
        self.values
            .lock()
            .unwrap()
            .get("context_session_token")
            .cloned()
    }
}

fn endpoint() -> ContextEndpoint {
    ContextEndpoint::parse("https://context.example.test").unwrap()
}

fn signed(actor: &str, token: &str) -> SignedIn {
    SignedIn {
        token: zeroize::Zeroizing::new(token.to_string()),
        principal: PrincipalKey::new(&endpoint(), "default-org", actor, 1).unwrap(),
        destinations: vec![DestinationKey::new("team").unwrap()],
        display_name: "Alice".into(),
    }
}

const TOKEN_A: &str = "vox_sso_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
const TOKEN_B: &str = "vox_sso_BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB";

#[test]
fn a_second_sign_in_never_replaces_an_active_account() {
    let store = MemoryStore::default();
    let slot = AccountSlot::default();
    let first = slot.begin_sign_in().unwrap();
    assert_eq!(
        slot.begin_sign_in().err(),
        Some(AccountError::SignInInProgress)
    );
    slot.publish(
        &first,
        endpoint(),
        signed("alice", TOKEN_A),
        store.clone(),
        None,
    )
    .unwrap();
    drop(first);
    assert_eq!(
        slot.begin_sign_in().err(),
        Some(AccountError::AlreadySignedIn)
    );
    assert_eq!(store.token().as_deref(), Some(TOKEN_A));
    assert_eq!(slot.display_name().as_deref(), Some("Alice"));
}

#[test]
fn signing_out_during_a_sign_in_cancels_it_and_stores_nothing() {
    let store = MemoryStore::default();
    let slot = AccountSlot::default();
    let ticket = slot.begin_sign_in().unwrap();
    let ended = slot.end(|| store.clone());
    assert!(ended.store_cleared);
    assert_eq!(
        slot.publish(
            &ticket,
            endpoint(),
            signed("alice", TOKEN_A),
            store.clone(),
            None
        )
        .err(),
        Some(AccountError::Cancelled)
    );
    assert_eq!(store.token(), None);
    assert!(slot.current().is_none());
}

#[test]
fn sign_out_clears_the_store_before_a_new_sign_in_can_write_it() {
    let store = MemoryStore::default();
    let slot = AccountSlot::default();
    let ticket = slot.begin_sign_in().unwrap();
    slot.publish(
        &ticket,
        endpoint(),
        signed("alice", TOKEN_A),
        store.clone(),
        None,
    )
    .unwrap();
    drop(ticket);
    let old = slot.current().unwrap();
    let ended = slot.end(|| store.clone());
    assert!(ended.store_cleared);
    assert_eq!(
        ended.logout.as_ref().map(|(_, token)| token.as_str()),
        Some(TOKEN_A),
        "the old token is kept only for the server logout"
    );
    assert_eq!(store.token(), None, "cleared inside the sign-out itself");

    let ticket = slot.begin_sign_in().unwrap();
    slot.publish(
        &ticket,
        endpoint(),
        signed("bob", TOKEN_B),
        store.clone(),
        None,
    )
    .unwrap();
    // A late refusal for the old session must not touch the new one.
    slot.end_if(&old);
    assert_eq!(store.token().as_deref(), Some(TOKEN_B));
    assert!(slot.current().is_some_and(|s| s.signed_in()));
    let new = slot.current().unwrap();
    slot.end_if(&new);
    assert_eq!(store.token(), None);
    assert!(slot.current().is_none());
}

#[test]
fn signing_out_without_a_session_still_clears_a_leftover_and_reports_failure_honestly() {
    let store = MemoryStore::default();
    store
        .values
        .lock()
        .unwrap()
        .insert("context_session_token".into(), TOKEN_A.into());
    let slot: AccountSlot<MemoryStore> = AccountSlot::default();
    let ended = slot.end(|| store.clone());
    assert!(ended.store_cleared && ended.logout.is_none());
    assert_eq!(store.token(), None);

    *store.broken.lock().unwrap() = true;
    assert!(!slot.end(|| store.clone()).store_cleared);
}

#[test]
fn a_store_that_cannot_save_leaves_no_account() {
    let store = MemoryStore::default();
    *store.broken.lock().unwrap() = true;
    let slot = AccountSlot::default();
    let ticket = slot.begin_sign_in().unwrap();
    assert_eq!(
        slot.publish(
            &ticket,
            endpoint(),
            signed("alice", TOKEN_A),
            store.clone(),
            None
        )
        .err(),
        Some(AccountError::StoreUnavailable)
    );
    assert!(slot.current().is_none());
    assert_eq!(slot.display_name(), None);
}
